// Run with `bun test`. Replays fixtures generated by the Go simulation and
// requires identical results, proving the browser and server agree.
import { describe, expect, test } from "bun:test";
import fixtures from "./fixtures.json";
import { HEIGHT, Sim, WIDTH } from "./sim";

interface Fixture {
  seed: number;
  ticks: number;
  events: [number, number][];
  want: { tick: number; score: number; lines: number; over: boolean; piece: { kind: number; rot: number; row: number; col: number }; board: string };
}

function replay(f: Fixture) {
  const s = new Sim(f.seed);
  let i = 0;
  const buf: number[] = [];
  while (s.tick < f.ticks && !s.over) {
    buf.length = 0;
    while (i < f.events.length && f.events[i][0] === s.tick) buf.push(f.events[i++][1]);
    s.step(buf);
  }
  return s;
}

describe("stackfall sim matches the Go implementation", () => {
  (fixtures as Fixture[]).forEach((f, n) => {
    test(`fixture ${n} (seed ${f.seed})`, () => {
      const s = replay(f);
      let board = "";
      for (let r = 0; r < HEIGHT; r++) for (let c = 0; c < WIDTH; c++) board += String(s.cell(r, c));
      expect(s.tick).toBe(f.want.tick);
      expect(s.score).toBe(f.want.score);
      expect(s.lines).toBe(f.want.lines);
      expect(s.over).toBe(f.want.over);
      expect(s.piece).toEqual(f.want.piece);
      expect(board).toBe(f.want.board);
    });
  });
});
